#include <iostream>

// Precondicion del prototipo: 0 <= piezas <= 10.
int estimar(int piezas) {
    if (piezas == 0) {
        return 0;
    }
    return 3 + 2 * piezas;
}

int main() {
    std::cout << estimar(0) << ":" << estimar(4);
    return 0;
}

